          "As part of your consultation, Dr Adnan will undertake a detailed examination of your nose, taking into account its measurements. He will discuss your expectations of tertiary rhinoplasty and advise you on realistic goals.",
          "ItΓÇÖs important for patients to understand that scarring is likely with tertiary revision rhinoplasty. You should also follow Dr AdnanΓÇÖs post-op care recommendations for a quick recovery."
